def omega(n):
    if n == 1:
        return 0
    count = 0
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            count += 1
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        count += 1
    return count

results = {}
for n in range(1, 16):
    w = omega(n)
    results[n] = {'omega': w, 'predicted_N': 2**w}

print("n | omega(n) | Predicted N(n)")
for n, data in results.items():
    print(f"{n:2} | {data['omega']:8} | {data['predicted_N']}")

